mapper.update:
update articles
title=#{title}, slug=#{slug}, summary=#{summary}, cover_image=#{coverImage}, content_markdown=#{contentMarkdown}, content_html=#{contentHtml}, category_id=#{categoryId}, is_published=#{isPublished}, is_top=#{isTop}, update_time=NOW()
where id=#{id}

mapper.delete:
delete from articles
where id in

    #{id}

mapper.select:
select a.id,a.title,a.slug,a.summary,a.cover_image as coverImage,a.category_id as categoryId, ac.name as categoryName, a.view_count as viewCount,a.like_count as likeCount,a.comment_count as commentCount, a.word_count as wordCount,a.reading_time as readingTime, a.is_published as isPublished,a.is_top as isTop, a.publish_time as publishTime,a.create_time as createTime,a.update_time as updateTime from articles a left join article_categories ac on a.category_id = ac.id where
title like concat('%',#{title},'%')
and a.category_id=#{categoryId}
and a.is_published=#{isPublished}
order by a.create_time desc
